// scanMutatingRepoInterfaceMethods walks every non-test .go file directly in dir (no recursion),
// finds every `type X interface { ... }` declaration, and returns "X.MethodName" for every
// directly-declared (non-embedded) exported method whose name satisfies looksMutating.
//
// This is a syntax-only AST walk (go/parser, no type-checking): it does not resolve embedded
// interfaces, so a mutating method reached only through embedding would not be found here. No
// interface in this package currently embeds another that contributes a mutating method (verified
// by inspection while building this guard); a future one would need this scanner extended.
func scanMutatingRepoInterfaceMethods(dir string) (map[string]bool, error) {
	entries, err := os.ReadDir(dir)
	if err != nil {
		return nil, err
	}

	found := map[string]bool{}
	fset := token.NewFileSet()
	for _, e := range entries {
		name := e.Name()
		if e.IsDir() || !strings.HasSuffix(name, ".go") || strings.HasSuffix(name, "_test.go") {
			continue
		}
		path := filepath.Join(dir, name)
		file, err := parser.ParseFile(fset, path, nil, 0)
		if err != nil {
			return nil, err
		}

		for _, decl := range file.Decls {
			gd, ok := decl.(*ast.GenDecl)
			if !ok || gd.Tok != token.TYPE {
				continue
			}
			for _, spec := range gd.Specs {
				ts, ok := spec.(*ast.TypeSpec)
				if !ok {
					continue
				}
				iface, ok := ts.Type.(*ast.InterfaceType)
				if !ok {
					continue
				}
				ifaceName := ts.Name.Name
				for _, m := range iface.Methods.List {
					if len(m.Names) == 0 {
						continue // embedded interface, not a directly-declared method
					}
					methodName := m.Names[0].Name
					if looksMutating(methodName) {
						found[ifaceName+"."+methodName] = true
					}
				}
			}
		}
	}
	return found, nil
}

// TestEveryMutatingRepoMethodIsInReviewedAllowlist is completeness guard #1 (see the package doc
// comment above for what it does and does NOT prove).
func TestEveryMutatingRepoMethodIsInReviewedAllowlist(t *testing.T) {
	found, err := scanMutatingRepoInterfaceMethods(".")
	if err != nil {
		t.Fatalf("scanning repository interfaces: %v", err)
	}
	if len(found) == 0 {
		t.Fatal("scanned zero mutating interface methods — guard is looking at the wrong directory " +
			"or looksMutating broke; a silently-empty scan is worse than no guard at all")
	}

	var missing []string
	for key := range found {
		d, ok := repoMethodDispositions[key]
		if !ok {
			missing = append(missing, key)
			continue
		}
		switch d.kind {
		case dispositionExplicitBump, dispositionCoveredByHTTPMiddleware, dispositionNoCacheImpact:
			if strings.TrimSpace(d.detail) == "" {
				t.Errorf("repoMethodDispositions[%q] has an empty detail — a bare entry defeats the "+
					"point of this guard", key)
			}
		case dispositionDerivedNoCacheImpact:
			// The inverse rule: a derived entry must NOT carry prose. Its claim is re-proven
			// mechanically every run, so a detail string here would be an unchecked human
			// assertion masquerading as evidence — exactly the failure mode #1537 exists to end.
			if strings.TrimSpace(d.detail) != "" {
				t.Errorf("repoMethodDispositions[%q] is dispositionDerivedNoCacheImpact but carries a "+
					"detail string. Derived entries are proven by write-set disjointness, not argued; "+
					"if the claim needs prose it is not derived — use dispositionNoCacheImpact.", key)
			}
		default:
			// Unreachable today. Present so that adding a new kind without deciding how the guard
			// treats it fails loudly instead of silently passing every entry that uses it.
			t.Errorf("repoMethodDispositions[%q] has disposition kind %d, which this guard does not "+
				"know how to validate — teach it, do not leave the kind unchecked", key, int(d.kind))
		}
	}

	if len(missing) > 0 {
		t.Errorf("%d mutating repository method(s) are missing from repoMethodDispositions "+
			"entirely: %s", len(missing), strings.Join(missing, ", "))
	}

}

// TestNoStaleDispositionEntries is the reverse direction: the guard above proves map ⊇ scan (no
// mutating method lacks an entry), and this proves scan ⊇ map (no entry describes a method that no
// longer exists). Without it the map can rot into fiction — an entry for a deleted or renamed
// method keeps its reassuring prose forever, and the detail-validation loop never even looks at it,
// because that loop iterates the SCAN, not the map. Zero stale entries today, so adding this costs
// nothing now and prevents the drift later.
func TestNoStaleDispositionEntries(t *testing.T) {
	found, err := scanMutatingRepoInterfaceMethods(".")
	if err != nil {
		t.Fatalf("scanning repository interfaces: %v", err)
	}
	if len(found) == 0 {
		t.Fatal("scanned zero mutating interface methods — a silently-empty scan would make every " +
			"map entry look stale")
	}
	var stale []string
	for key := range repoMethodDispositions {
		if !found[key] {
			stale = append(stale, key)
		}
	}
	sort.Strings(stale)
	if len(stale) > 0 {
		t.Errorf("%d disposition entr(ies) describe methods this package no longer declares: %s\n"+
			"Delete them. A stale entry is worse than a missing one: it reads as reviewed coverage "+
			"for something that does not exist, and if the name is ever reused the old prose is "+
			"silently inherited by a different method.", len(stale), strings.Join(stale, ", "))
	}
}
